namespace Tetitulz.Pdf.TestHelpers;

/// <summary>
/// Compact ICC profiles from Clinton Ingram's Compact-ICC-Profiles (saucecontrol/Compact-ICC-Profiles on GitHub),
/// released to the public domain under CC0 1.0: real matrix/TRC profiles, base64, for the colour engine's tests and
/// the PDF/A converter's.
/// </summary>
public static class CompactIccProfiles
{
    /// <summary>sRGB-v4.icc, 480 bytes.</summary>
    public const string sRgbv4 = "";

    /// <summary>DisplayP3-v4.icc, 480 bytes.</summary>
    public const string DisplayP3v4 = "";

    /// <summary>AdobeCompat-v4.icc, 480 bytes (Adobe RGB 1998's primaries and gamma).</summary>
    public const string AdobeCompatv4 = "";

    /// <summary>sGrey-v4.icc, 360 bytes.</summary>
    public const string sGreyv4 = "";

    /// <summary>A profile's bytes.</summary>
    public static byte[] Bytes(string base64) => System.Convert.FromBase64String(base64);
}